fn string_xor(a: Vec<char>, b: Vec<char>) -> Vec<char> {
    // Ensure both vectors have the same length (as per problem statement)
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    
    // Create result vector with pre-allocated capacity
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate through both vectors simultaneously
    for (char_a, char_b) in a.iter().zip(b.iter()) {
        // Validate input characters (optional but good practice)
        assert!(*char_a == '0' || *char_a == '1', "Input a contains invalid character: {}", char_a);
        assert!(*char_b == '0' || *char_b == '1', "Input b contains invalid character: {}", char_b);
        
        // Compute XOR: '1' if characters are different, '0' if they are the same
        let xor_char = if char_a != char_b { '1' } else { '0' };
        result.push(xor_char);
    }
    
    result
}